changeSet.sql:
DO $$
DECLARE
    entity_col text;
    join_tbl text;
BEGIN
    CREATE TEMP TABLE stale_form_config_answer (id bigint PRIMARY KEY) ON COMMIT DROP;

    FOREACH entity_col IN ARRAY ARRAY['fk_recording_unit_id', 'fk_specimen_id', 'fk_phase_id', 'fk_container_id']
    LOOP
        EXECUTE format(
            'INSERT INTO stale_form_config_answer (id)
             SELECT form_config_answer_id FROM (
                 SELECT form_config_answer_id,
                        row_number() OVER (PARTITION BY %1$I, fk_form_config_id
                                           ORDER BY form_config_answer_id DESC) AS rn
                 FROM form_config_answer
                 WHERE %1$I IS NOT NULL
             ) ranked
             WHERE rn > 1
             ON CONFLICT DO NOTHING', entity_col);
    END LOOP;

    FOREACH join_tbl IN ARRAY ARRAY[
        'custom_field_answer_concept_answers',
        'custom_field_answer_person_answers',
        'custom_field_answer_spatial_unit_answers',
        'custom_field_answer_action_unit_answers',
        'custom_field_answer_action_code_answers']
    LOOP
        IF to_regclass(join_tbl) IS NOT NULL THEN
            EXECUTE format('DELETE FROM %I WHERE fk_form_config_answer_id IN (SELECT id FROM stale_form_config_answer)', join_tbl);
        END IF;
    END LOOP;

    DELETE FROM custom_field_answer WHERE fk_form_config_answer_id IN (SELECT id FROM stale_form_config_answer);
    DELETE FROM form_config_answer WHERE form_config_answer_id IN (SELECT id FROM stale_form_config_answer);
END $$;
